end

do -- SECTION raw_subtract_u64
local function raw_subtract_u64(lhs_lo, lhs_hi, rhs_lo, rhs_hi)
	local lo = lhs_lo - rhs_lo
	local hi = lhs_hi - rhs_hi

	if lo < 0 then
		lo = lo + 0x100000000
		hi = hi - 1
	end

	return lo, hi
end
